import{_ as e,o as n,c as s,a2 as l}from"./chunks/framework.mRCPFc5l.js";const i="/assets/quality-summary.Ce1q45WT.png",o="/assets/spellchecker.BQBxNbUR.png",t="/assets/dictionary-manager.DXMUvTZ8.png",b=JSON.parse('{"title":"质量检查","description":"","frontmatter":{},"headers":[],"relativePath":"05-quality-checks.md","filePath":"zh-CN/05-quality-checks.md"}'),r={name:"05-quality-checks.md"};function d(p,a,c,h,g,u){return n(),s("div",null,[...a[0]||(a[0]=[l('<h1 id="质量检查" tabindex="-1">质量检查 <a class="header-anchor" href="#质量检查" aria-label="Permalink to &quot;质量检查&quot;">​</a></h1><p>集中发现并处理阅读速度、行长、时间和拼写问题。</p><h2 id="你可以在本页完成什么" tabindex="-1">你可以在本页完成什么 <a class="header-anchor" href="#你可以在本页完成什么" aria-label="Permalink to &quot;你可以在本页完成什么&quot;">​</a></h2><ul><li>使用项目阈值定位长译文和高 CPS 字幕。</li><li>跳转到缺少集数、缺少译文、无效时间或时间重叠的行。</li><li>使用本地词典检查译文拼写。</li><li>管理忽略词和用户词典。</li></ul><h2 id="设置质量检查标准" tabindex="-1">设置质量检查标准 <a class="header-anchor" href="#设置质量检查标准" aria-label="Permalink to &quot;设置质量检查标准&quot;">​</a></h2><p>在 <strong>项目设置 → 其他参数</strong> 中设置：</p><ul><li><strong>最大 CPS</strong>：每秒允许的最大译文字符数。</li><li><strong>行长</strong>：单行译文的建议最大字符数，也用于断行工具。</li><li><strong>拼写检查语言</strong>：当前项目使用的已安装词典。</li></ul><p>这些阈值用于提示和筛选，不会自动修改字幕。</p><h2 id="查找过长字幕" tabindex="-1">查找过长字幕 <a class="header-anchor" href="#查找过长字幕" aria-label="Permalink to &quot;查找过长字幕&quot;">​</a></h2><p>表格工具栏显示 <strong>长行：数量</strong>。点击它可以只显示超出行长阈值的字幕，再次关闭筛选可回到完整工作区。</p><p>字符数保留空格，但不计算真实换行或字幕换行符。可根据语义选择缩短译文、使用 <strong>断行</strong>，或使用 <strong>拆分</strong> 生成多条字幕。</p><h2 id="查找阅读速度过高的字幕" tabindex="-1">查找阅读速度过高的字幕 <a class="header-anchor" href="#查找阅读速度过高的字幕" aria-label="Permalink to &quot;查找阅读速度过高的字幕&quot;">​</a></h2><p>点击 <strong>高 CPS：数量</strong> 筛选问题行。CPS 根据译文字符数和字幕持续时间计算。</p><p>常见处理方式：</p><ul><li>精简译文。</li><li>在不影响画面和语义的前提下延长时间。</li><li>拆分信息过多的字幕。</li></ul><p>修改译文或时间后，字符数和 CPS 会自动更新。</p><h2 id="检查字幕时间和完整性" tabindex="-1">检查字幕时间和完整性 <a class="header-anchor" href="#检查字幕时间和完整性" aria-label="Permalink to &quot;检查字幕时间和完整性&quot;">​</a></h2><p>表格底部/侧边摘要会显示校验状态。可能的项目包括：</p><ul><li><strong>无效时间范围</strong>：时间缺失、格式不可用或结束不晚于开始。</li><li><strong>缺少分集</strong>：字幕行没有有效集数。</li><li><strong>缺少译文</strong>：译文字段为空。</li><li><strong>时间重叠</strong>：同一集相邻字幕范围发生重叠。</li></ul><p><img src="'+i+'" alt="质量摘要显示无效时间、缺少译文和时间重叠等警告"></p><p>点击对应摘要会跳到下一个问题行，而不是把其他字幕隐藏。反复点击可循环检查同类问题。</p><p>时间编辑器会在应用重叠或顺序变化前再次提醒。校验提示不是自动修复；应结合视频确认正确时间。</p><h2 id="启用拼写检查" tabindex="-1">启用拼写检查 <a class="header-anchor" href="#启用拼写检查" aria-label="Permalink to &quot;启用拼写检查&quot;">​</a></h2><ol><li>打开 <strong>设置</strong>。</li><li>启用 <strong>检查译文拼写</strong>。</li><li>点击 <strong>词典</strong>，选择一个已安装词典。</li><li>等待后台检查完成。</li></ol><p>拼写检查只扫描 <code>translation</code> 字段。大型工作区会分批处理，检查过程中仍可编辑。没有安装词典时，拼写检查器按钮不可用。</p><h2 id="查看和应用拼写建议" tabindex="-1">查看和应用拼写建议 <a class="header-anchor" href="#查看和应用拼写建议" aria-label="Permalink to &quot;查看和应用拼写建议&quot;">​</a></h2><p>按 <code>F7</code> 或点击 <strong>拼写检查</strong> 打开检查器。</p><p><img src="'+o+`" alt="拼写检查器显示当前错词、建议和处理按钮"></p><ol><li>使用 <strong>上一个</strong>、<strong>下一个</strong> 在错误间导航。</li><li>在建议列表中选择替换词。</li><li>点击 <strong>应用</strong> 修改当前单元格。</li></ol><p>跳转时表格会跟随目标行。直接在表格中修正拼写也会更新检查结果，并尽量保持当前编辑焦点。</p><h2 id="忽略拼写提示" tabindex="-1">忽略拼写提示 <a class="header-anchor" href="#忽略拼写提示" aria-label="Permalink to &quot;忽略拼写提示&quot;">​</a></h2><ul><li><strong>忽略一次</strong>：只移除当前出现，其他相同单词仍会提示。</li><li><strong>全部忽略</strong>：在当前工作区忽略该词的所有出现。</li><li><strong>添加到词典</strong>：把词加入当前词典的用户词典，适合人名、专有名词等长期有效内容。</li></ul><p>这些操作会更新拼写统计，但不会改变正在使用的字幕筛选。</p><h2 id="安装和切换拼写词典" tabindex="-1">安装和切换拼写词典 <a class="header-anchor" href="#安装和切换拼写词典" aria-label="Permalink to &quot;安装和切换拼写词典&quot;">​</a></h2><p>GridSubStudio 使用 Hunspell 格式词典，但不内置、下载或推荐具体词典。安装前请从可信来源取得适合目标语言和地区的词典，并确认其许可证允许你的使用方式。</p><h3 id="认识-hunspell-词典文件" tabindex="-1">认识 Hunspell 词典文件 <a class="header-anchor" href="#认识-hunspell-词典文件" aria-label="Permalink to &quot;认识 Hunspell 词典文件&quot;">​</a></h3><p>一套 Hunspell 词典至少包含两个配套文件：</p><ul><li><code>.dic</code> 是词条文件。第一行通常是词条数量，后续每行是一个词及其可选规则标记。</li><li><code>.aff</code> 是规则文件，声明字符编码、前缀和后缀变化、替换与建议等规则。</li></ul><p>两个文件必须来自同一套词典。不要把一个语言的 <code>.aff</code> 与另一个语言的 <code>.dic</code> 混用，也不要只复制 <code>.dic</code>。下载包中常见的文件名是 <code>en_US.aff</code>/<code>en_US.dic</code>、<code>de_DE.aff</code>/<code>de_DE.dic</code>；复制到 GridSubStudio 后，需要在各自子文件夹内改名为固定的 <code>index.aff</code> 和 <code>index.dic</code>。</p><p>应用会读取 <code>.aff</code> 中声明的编码和规则。除非你了解 Hunspell 格式，否则不要用文本编辑器重新保存、转换编码或改动规则标记，否则可能出现词典无法加载、正常词被误报或建议异常。</p><h3 id="放入词典文件" tabindex="-1">放入词典文件 <a class="header-anchor" href="#放入词典文件" aria-label="Permalink to &quot;放入词典文件&quot;">​</a></h3><p>在 <strong>设置 → 词典</strong> 中：</p><ol><li>点击 <strong>打开文件夹</strong>。</li><li>如果下载的是 ZIP 或其他压缩包，先完整解压；不要直接把压缩包放入词典目录。</li><li>为每套词典建立一个单独子文件夹，例如 <code>en_US</code> 或 <code>de_DE</code>。子文件夹名就是应用中显示的词典名称。</li><li>把配套的 <code>.aff</code> 和 <code>.dic</code> 放入该子文件夹，并分别命名为 <code>index.aff</code> 和 <code>index.dic</code>。</li><li>可以保留词典随附的 <code>LICENSE</code>、<code>COPYING</code> 或 <code>README</code> 作为许可记录；应用不会解析这些附加文件。</li><li>回到应用点击 <strong>刷新</strong>。</li><li>点击词典名称将其设为“启用中”。</li></ol><p>目录结构应类似：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>词典安装目录/</span></span>
<span class="line"><span>  en_US/</span></span>
<span class="line"><span>    index.aff</span></span>
<span class="line"><span>    index.dic</span></span>
<span class="line"><span>    LICENSE          （可选）</span></span>
<span class="line"><span>  de_DE/</span></span>
<span class="line"><span>    index.aff</span></span>
<span class="line"><span>    index.dic</span></span></code></pre></div><p>应用只扫描词典安装目录的直接子文件夹。以下结构不会被识别：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>词典安装目录/</span></span>
<span class="line"><span>  en_US.aff          （没有独立子文件夹）</span></span>
<span class="line"><span>  en_US.dic</span></span>
<span class="line"><span>  en_US/</span></span>
<span class="line"><span>    en_US.aff        （没有改为 index.aff）</span></span>
<span class="line"><span>    en_US.dic</span></span></code></pre></div><h3 id="切换和验证词典" tabindex="-1">切换和验证词典 <a class="header-anchor" href="#切换和验证词典" aria-label="Permalink to &quot;切换和验证词典&quot;">​</a></h3><p>刷新后，只有同时包含两个必需文件的子文件夹才会出现在“已安装”列表中。点击一个词典名称后，它会显示为“启用中”；关闭词典管理器后，应用按新词典重新检查全部译文。</p><p><img src="`+t+'" alt="词典管理器显示安装目录、已安装词典和管理入口"></p><p>可故意输入一个常见错词并运行拼写检查，确认能显示错误和建议。不同 Hunspell 实现对少数复杂形态规则的结果可能不同；GridSubStudio 使用兼容 Hunspell 格式的本地检查引擎，不保证与 LibreOffice、Firefox 或其他 Hunspell/Nuspell 程序逐词完全一致。</p><p>安装多套地区词典时应保留清楚的文件夹名，例如 <code>en_US</code>、<code>en_GB</code>。GridSubStudio 不会自动把 <code>en</code> 映射为某个地区版本，也不会在选中词典缺失时回退到其他词典。</p><h2 id="管理忽略词和用户词典" tabindex="-1">管理忽略词和用户词典 <a class="header-anchor" href="#管理忽略词和用户词典" aria-label="Permalink to &quot;管理忽略词和用户词典&quot;">​</a></h2><p>词典管理器提供：</p><ul><li><strong>忽略词</strong>：针对当前 CSV/项目工作区保存；可以添加词、勾选多项并移除。</li><li><strong>用户词典</strong>：属于当前词典，可跨项目使用；可以添加或批量移除自定义词。</li></ul><p>在嵌套管理窗口关闭并返回词典管理器后，应用会统一重新检查，避免每次增删词都触发全量扫描。</p><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><ul><li><strong>刷新后没有出现词典</strong>：确认文件已经解压，位于安装目录的直接子文件夹中，并且准确命名为 <code>index.aff</code> 和 <code>index.dic</code>。</li><li><strong>词典无法加载</strong>：确认两个文件来自同一词典包，没有被编辑器改写编码；尝试重新从原始压缩包提取。</li><li><strong>选中的词典突然不可用</strong>：不要依赖自动回退。恢复原文件夹，或刷新后明确选择另一个已安装词典。</li><li><strong>刚改词典但结果未更新</strong>：关闭忽略词/用户词典窗口，再关闭词典管理器触发检查。</li><li><strong>没有建议</strong>：可以手动编辑、忽略一次，或在确认拼写正确时添加到词典。</li><li><strong>结果与其他软件不同</strong>：复杂词形规则可能存在兼容性差异；先核对词典版本和地区，再用实际字幕样例验证。</li><li><strong>检查大型项目较慢</strong>：可继续编辑；扫描会分批完成，避免阻塞工作区。</li></ul>',58)])])}const _=e(r,[["render",d]]);export{b as __pageData,_ as default};
